import contextlib
import io
import unittest

from textkit.cli import main
from textkit.roman import from_roman, to_roman


def run(*argv):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class ToRomanTest(unittest.TestCase):
    def test_known_values(self):
        self.assertEqual(to_roman(1), "I")
        self.assertEqual(to_roman(4), "IV")
        self.assertEqual(to_roman(9), "IX")
        self.assertEqual(to_roman(14), "XIV")
        self.assertEqual(to_roman(40), "XL")
        self.assertEqual(to_roman(1994), "MCMXCIV")
        self.assertEqual(to_roman(3999), "MMMCMXCIX")

    def test_bounds_raise(self):
        for n in (0, 4000, -1):
            with self.subTest(n=n), self.assertRaises(ValueError):
                to_roman(n)

    def test_non_integer_raises(self):
        for n in (1.5, "5", None):
            with self.subTest(n=n), self.assertRaises(ValueError):
                to_roman(n)


class FromRomanTest(unittest.TestCase):
    def test_known_values(self):
        self.assertEqual(from_roman("I"), 1)
        self.assertEqual(from_roman("XLII"), 42)
        self.assertEqual(from_roman("MCMXCIV"), 1994)
        self.assertEqual(from_roman("MMMCMXCIX"), 3999)

    def test_non_canonical_raises(self):
        for s in ("IIII", "IC", "VX", "mcm", "", "VV", "IIV", "XXXX", "MMMM", "CMM", "ABC", " I", "I "):
            with self.subTest(s=s), self.assertRaises(ValueError):
                from_roman(s)

    def test_round_trip_every_value(self):
        for n in range(1, 4000):
            with self.subTest(n=n):
                self.assertEqual(from_roman(to_roman(n)), n)


class RomanCommandTest(unittest.TestCase):
    def test_digits_print_numeral(self):
        self.assertEqual(run("roman", "1994"), (0, "MCMXCIV\n", ""))

    def test_numeral_prints_integer(self):
        self.assertEqual(run("roman", "MCMXCIV"), (0, "1994\n", ""))

    def test_invalid_numeral_exits_2_with_error(self):
        code, out, err = run("roman", "IIII")
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error: "))

    def test_out_of_range_digits_exit_2_with_error(self):
        for value in ("0", "4000"):
            with self.subTest(value=value):
                code, out, err = run("roman", value)
                self.assertEqual(code, 2)
                self.assertEqual(out, "")
                self.assertTrue(err.startswith("error: "))

